"""Bot Bastion baked-isometric sprite pack: Blender-side kit (ORIGINAL, generated by project scripts).

Imported by bb_bake.py, which is run headless:
    blender -b --python bb_bake.py -- <rawdir> [group,group,...]

Helpers (materials, primitives, lighting rig) are adapted from
docs/design/tower-defence/bot-bastion-3d/renders/make_models.py (same palette, same rig).
Bake convention: orthographic camera, elevation 50 deg, yaw 0, +Y = up-screen, +X = right.
Facing k (0..7) = heading 45*k degrees counter-clockwise from +X. Models are built facing +Y.
"""
import bpy, math, random, sys, os
from mathutils import Vector

ARGS = sys.argv[sys.argv.index("--") + 1:]
OUT = ARGS[0]
ONLY = set(ARGS[1].split(",")) if len(ARGS) > 1 and ARGS[1] else None
os.makedirs(OUT, exist_ok=True)
PPU = 100.0          # final baked pixels per game unit (renders are 2x supersampled)
SS = 2
ELEV = 50.0

bpy.ops.wm.read_factory_settings(use_empty=True)
sc = bpy.context.scene


def hexrgb(h):
    h = h.lstrip("#")
    c = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    return tuple(((x + 0.055) / 1.055) ** 2.4 if x > 0.04045 else x / 12.92 for x in c)


_mc = {}


def mat(name, rgb, rough=0.55, metal=0.0, emit=None, estr=0.0, alpha=1.0):
    key = (name, rgb, rough, metal, emit, estr, alpha)
    if key in _mc:
        return _mc[key]
    m = bpy.data.materials.new(name)
    m.use_nodes = True
    b = m.node_tree.nodes["Principled BSDF"]
    b.inputs["Base Color"].default_value = (*rgb, 1)
    b.inputs["Roughness"].default_value = rough
    b.inputs["Metallic"].default_value = metal
    if alpha < 1:
        b.inputs["Alpha"].default_value = alpha
    if emit:
        b.inputs["Emission Color"].default_value = (*emit, 1)
        b.inputs["Emission Strength"].default_value = estr
    _mc[key] = m
    return m


def gl(h, s=2.2, rough=0.3):
    return mat("gl" + h + str(s), hexrgb(h), rough, 0, hexrgb(h), s)


def solid(h, rough=0.7, metal=0.0):
    return mat("s" + h, hexrgb(h), rough, metal)


HULL = mat("hull_navy", hexrgb("#2B3A72"), 0.5, 0.15)
HULL2 = mat("hull_steel", hexrgb("#7C8AA8"), 0.45, 0.3)
DARK = mat("dark_ink", hexrgb("#141A3A"), 0.7)
BRONZE = mat("hull_bronze", hexrgb("#5A4020"), 0.55, 0.2)
PLUM = mat("hull_plum", hexrgb("#6B2A68"), 0.5, 0.15)
ROCK = mat("rock", hexrgb("#7A5C58"), 0.9)
ROCK2 = mat("rock_light", hexrgb("#A8786A"), 0.9)
ROCKD = mat("rock_dark", hexrgb("#4A3636"), 0.9)
PLATE = mat("plate_steel", hexrgb("#5B4B4A"), 0.6, 0.35)
WHITE = mat("hull_white", hexrgb("#DCE4F5"), 0.4, 0.1)
GOLD = mat("gold", hexrgb("#E8B545"), 0.35, 0.6)
TEAL = mat("hull_teal", hexrgb("#2A5C66"), 0.5, 0.2)
VIOHULL = mat("hull_violet", hexrgb("#4A3A8A"), 0.5, 0.15)
MINTHULL = mat("hull_mint", hexrgb("#2F6B58"), 0.5, 0.15)
CY, AM, VI, MG, MINT = gl("#4FE3FF"), gl("#FFB547"), gl("#B58CFF"), gl("#FF4FD8"), gl("#6BFF9E", 1.6)
RED = gl("#FF6B5A", 1.8)
EMB = gl("#FF8A3D", 2.4)
BLUE = gl("#5FA8FF", 2.0)


def finish(obj, m, flat=True):
    obj.data.materials.clear()
    obj.data.materials.append(m)
    if flat:
        for p in obj.data.polygons:
            p.use_smooth = False


def cyl(name, r, h, seg, loc=(0, 0, 0), rot=(0, 0, 0), m=HULL, r2=None):
    bpy.ops.mesh.primitive_cone_add(vertices=seg, radius1=r, radius2=(r if r2 is None else r2), depth=h, location=loc, rotation=rot)
    o = bpy.context.active_object
    o.name = name
    finish(o, m)
    return o


def box(name, sx, sy, sz, loc=(0, 0, 0), rot=(0, 0, 0), m=HULL):
    bpy.ops.mesh.primitive_cube_add(size=1, location=loc, rotation=rot)
    o = bpy.context.active_object
    o.name = name
    o.scale = (sx, sy, sz)
    bpy.ops.object.transform_apply(scale=True)
    finish(o, m)
    return o


def sph(name, r, loc=(0, 0, 0), seg=10, rings=6, scale=(1, 1, 1), m=HULL, smooth=False):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=seg, ring_count=rings, radius=r, location=loc)
    o = bpy.context.active_object
    o.name = name
    o.scale = scale
    bpy.ops.object.transform_apply(scale=True)
    finish(o, m, flat=not smooth)
    return o


def ico(name, r, loc, m, sub=1, scale=(1, 1, 1), jitter=0.0, seed=1, rot=(0, 0, 0)):
    bpy.ops.mesh.primitive_ico_sphere_add(subdivisions=sub, radius=r, location=loc, rotation=rot)
    o = bpy.context.active_object
    o.name = name
    if jitter:
        rnd = random.Random(seed)
        for v in o.data.vertices:
            v.co *= (1 - jitter / 2 + rnd.random() * jitter)
    o.scale = scale
    bpy.ops.object.transform_apply(scale=True)
    finish(o, m)
    return o


def torus(name, R, r, loc, rot=(0, 0, 0), m=HULL2, ms=14, mn=4):
    bpy.ops.mesh.primitive_torus_add(major_segments=ms, minor_segments=mn, major_radius=R, minor_radius=r, location=loc, rotation=rot)
    o = bpy.context.active_object
    o.name = name
    finish(o, m)
    return o


def join(objs, name):
    bpy.ops.object.select_all(action="DESELECT")
    for o in objs:
        o.select_set(True)
    bpy.context.view_layer.objects.active = objs[0]
    bpy.ops.object.join()
    o = bpy.context.active_object
    o.name = name
    bpy.context.scene.cursor.location = (0, 0, 0)
    bpy.ops.object.origin_set(type="ORIGIN_CURSOR")
    return o


def purge():
    for o in list(bpy.data.objects):
        if o.type == "MESH":
            d = o.data
            bpy.data.objects.remove(o, do_unlink=True)
            if d.users == 0:
                bpy.data.meshes.remove(d)


# --------------------------------------------------------------------------- scene rig
_w = bpy.data.worlds.new("w")
sc.world = _w
_w.use_nodes = True
bgn = _w.node_tree.nodes["Background"]


def light(name, energy, rgb, rot, size):
    d = bpy.data.lights.new(name, "SUN")
    d.energy = energy
    d.color = rgb
    d.angle = size
    o = bpy.data.objects.new(name, d)
    bpy.context.collection.objects.link(o)
    o.location = (0, 0, 5)
    o.rotation_euler = rot
    return o


KEY = light("key", 3.2, (1.0, 0.93, 0.82), (math.radians(50), math.radians(10), math.radians(-35)), 0.12)
RIM = light("rim", 1.6, (0.45, 0.7, 1.0), (math.radians(65), 0, math.radians(150)), 0.2)
FILL = light("fill", 0.5, (0.8, 0.8, 1.0), (math.radians(30), 0, math.radians(100)), 0.5)
ALARM = light("alarm", 0.0, (1.0, 0.2, 0.15), (math.radians(60), 0, math.radians(-120)), 0.2)


def set_rig(key=(1.0, 0.93, 0.82), rim=(0.45, 0.7, 1.0), kE=3.2, rE=1.6, fE=0.5, alarm=0.0, world="#0E1226", wS=0.8):
    KEY.data.color = key
    KEY.data.energy = kE
    RIM.data.color = rim
    RIM.data.energy = rE
    FILL.data.energy = fE
    ALARM.data.energy = alarm
    bgn.inputs[0].default_value = (*hexrgb(world), 1)
    bgn.inputs[1].default_value = wS


set_rig()
cam_d = bpy.data.cameras.new("cam")
cam_d.type = "ORTHO"
cam = bpy.data.objects.new("cam", cam_d)
bpy.context.collection.objects.link(cam)
sc.camera = cam
for _eng in ("BLENDER_EEVEE", "BLENDER_EEVEE_NEXT", "CYCLES"):
    try:
        sc.render.engine = _eng
        break
    except Exception:
        continue
try:
    sc.eevee.taa_render_samples = 16
except Exception:
    pass
sc.render.film_transparent = True
sc.render.image_settings.file_format = "PNG"
sc.render.image_settings.color_mode = "RGBA"
sc.view_settings.view_transform = "Standard"

INDEX = []


def shoot(name, cellw, cellh, gscale, lz=0.0, meta=None, cx=0.0, cy=0.0, ppu=None):
    """Render the visible scene. gscale = game units per model unit. Camera looks at (cx, cy, lz) in model
    units. Output cell is cellw x cellh FINAL pixels at PPU px per game unit; the render is SS x larger.
    The anchor (model-space origin = the ground footprint centre) is recorded in final cell pixels."""
    ppu = ppu or PPU
    e = math.radians(ELEV)
    sc.render.resolution_x = cellw * SS
    sc.render.resolution_y = cellh * SS
    ppm = ppu * gscale
    cam_d.ortho_scale = max(cellw, cellh) / ppm
    L = Vector((cx, cy, lz))
    cam.location = L + Vector((0, -12 * math.cos(e), 12 * math.sin(e)))
    cam.rotation_euler = (L - cam.location).to_track_quat("-Z", "Y").to_euler()
    sc.render.filepath = os.path.join(OUT, name + ".png")
    bpy.ops.render.render(write_still=True)
    ax = cellw / 2 + (0 - cx) * ppm
    ay = cellh / 2 + (cy * math.sin(e) + lz * math.cos(e)) * ppm
    rec = {"name": name, "w": cellw, "h": cellh, "ax": round(ax, 2), "ay": round(ay, 2), "ppu": ppu}
    rec.update(meta or {})
    INDEX.append(rec)


def want(g):
    return ONLY is None or g in ONLY


def show_only(objs):
    s = set(id(o) for o in objs)
    for o in bpy.data.objects:
        if o.type == "MESH":
            o.hide_render = id(o) not in s
